const EVIDENCE={rh1:['比世界崩塌還沉重'],rh2:['前幾天燦爛地開着','已枯萎了'],rh3:['靈魂之窗'],rh4:['臉就泛紅了'],rh5:['失敗乃成功之母'],rh6:['一伸手就可以摸到天空'],rh7:['優良的傳統','落後的思想','保留','捨棄'],rh8:['你怎可以','枉你還説自己孝順'],rh9:['消防車來了','救護車來了','記者也來了'],rh10:['五岳歸來不看山','黃山歸來不看岳'],rh11:['是渴睡人的眼'],core1:['有團圓、圓滿的含義'],core2:['更好的廚具配合','錦上添花'],swap5:['供電','減少廢物'],swap8:['賺取生活費糊口'],extra4:['適量攝取鹽十分重要'],extra5:['帶來了無盡的快樂'],wt1:['首先','離開花圃','野餐點','穿過吊橋','水上樂園'],wt2:['從前','三年前','如今'],wt3:['相反','遠比飛機困難'],wt4:['蔚藍','蒼翠','紅豔','金黃','和煦的陽光','清爽的秋風','凜冽的寒風'],wt5:['漢拿山啊','慷慨','我的好友'],core5:['我班來了一位插班生','我很想念你'],swap3:['大家都在玩電子遊戲機'],swap4:['這件事令我明白了']};
const STORE='6e-language-lab-v2';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,extra='')=>`<span class="icon ${extra}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.star}</svg></span>`;
const uid=()=>globalThis.crypto?.randomUUID?.()||`s${Date.now()}${Math.random().toString(36).slice(2,10)}`;
const fmt=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const niceDate=s=>{try{return new Date(s).toLocaleString('zh-HK',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}catch{return s}};
const DEFAULT_SETTINGS={sound:false,reduced:false,projector:false,classroom:false,manualReveal:false};
let storageOK=true;
function load(){let d;try{d=JSON.parse(localStorage.getItem(STORE)||'null')}catch{};if(!d||d.version!==2)d={version:2,profiles:[{id:'guest',name:'訪客'}],active:'guest',records:[],activeGames:{},settings:{}};if(!Array.isArray(d.profiles)||!d.profiles.length)d.profiles=[{id:'guest',name:'訪客'}];if(!Array.isArray(d.records))d.records=[];if(!d.activeGames||typeof d.activeGames!=='object')d.activeGames={};d.settings={...DEFAULT_SETTINGS,...d.settings};if(!d.profiles.some(x=>x.id===d.active))d.active=d.profiles[0].id;return d}
let DB=load();
const S={screen:'home',stage:'mixed',game:null,modal:null,teacherTab:'controls',mobileTab:'question',startedAt:null,eliminate:false,pendingStart:null,lastFocus:null};
const profile=()=>DB.profiles.find(p=>p.id===DB.active)||DB.profiles[0];
function save(){try{localStorage.setItem(STORE,JSON.stringify(DB));storageOK=true}catch{storageOK=false}}
function curId(){return S.game?.qids[S.game.index]}
function curQ(){return Q[curId()]}
function draft(){return S.game.drafts[curId()]}
function outcome(){return S.game.outcomes[curId()]}
function isReduced(){return DB.settings.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches}
function applySettings(){document.body.classList.toggle('projector',DB.settings.projector);document.body.classList.toggle('reduced-motion',DB.settings.reduced);document.documentElement.style.setProperty('--reading',DB.settings.projector?'21px':'19px')}
function score(g){return Object.values(g.outcomes).reduce((s,r)=>s+(Number(r.points)||0),0)}
function graded(g){return Object.values(g.outcomes).filter(r=>r.status==='correct'||r.status==='wrong')}
function markCount(){return Object.keys(draft()?.marks||{}).length}
function revealed(){return !!outcome()&&(!DB.settings.manualReveal||draft().revealed)}
function startClock(){if(S.screen==='game'&&!S.modal&&!document.hidden&&!S.startedAt)S.startedAt=Date.now()}
function stopClock(){if(S.startedAt&&S.game){S.game.elapsed+=(Date.now()-S.startedAt)/1000;S.startedAt=null;save()}}
function timeNow(){return (S.game?.elapsed||0)+(S.startedAt?(Date.now()-S.startedAt)/1000:0)}
function iconButton(action,name,label,cls=''){return `<button type="button" class="iconbtn ${cls}" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}">${icon(name)}</button>`}
function header(){let p=profile();return `<header class="topbar"><button class="brand" data-action="home" aria-label="返回任務選單"><span class="brand-mark">文</span><span><strong>語文實驗室</strong><small>CHINESE LANGUAGE LAB / 6E</small></span></button><div class="top-tools"><span class="status"><i class="led"></i>離線就緒</span>${iconButton('sound',DB.settings.sound?'sound':'mute',DB.settings.sound?'關閉音效':'開啟音效',DB.settings.sound?'active':'')}${iconButton('fullscreen','expand','全螢幕','fullscreen-top')}${iconButton('settings','settings','設定','settings-top')}${iconButton('help','help','玩法說明','help-top')}<span class="top-divider"></span>${iconButton('teacher','teacher','課堂工具','teacher-top'+(DB.settings.classroom?' active':''))}<button class="pill playerpill" data-action="profile"><span class="avatar">${esc(p.name.slice(0,1))}</span><span class="player-label">${esc(p.name)}</span></button></div></header>`}
function footer(){return `<footer class="page-footer"><span>35道獨立題目 · 本機儲存，不會自動傳送成績</span><span class="hide-small">讀懂 → 判斷 → 找依據</span></footer>`}
function mount(html){applySettings();$('#app').innerHTML=header()+(!storageOK?'<div class="storage-warning">此瀏覽器未能儲存進度。離開前請在「答題紀錄」匯出備份。</div>':'')+html+footer()}
function heroArt(st){return `<svg viewBox="0 0 520 360" aria-hidden="true"><defs><linearGradient id="platform" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#9f8ade"/><stop offset="1" stop-color="#654cba"/></linearGradient><linearGradient id="face" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f9f6ff"/><stop offset="1" stop-color="#ded4f2"/></linearGradient><filter id="ds" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="0" dy="15" stdDeviation="10" flood-color="#6f55a7" flood-opacity=".16"/></filter></defs><circle cx="285" cy="180" r="139" fill="none" stroke="#b6a4d4" opacity=".24"/><circle cx="285" cy="180" r="164" fill="none" stroke="#b6a4d4" opacity=".2" stroke-dasharray="3 8"/><ellipse cx="280" cy="296" rx="170" ry="24" fill="#79639c" opacity=".09"/><path d="M69 273H124V306H195M362 74H440V127" fill="none" stroke="#c6b8dd" stroke-width="1.5"/><circle cx="69" cy="273" r="4" fill="#c5b4e5"/><circle cx="440" cy="127" r="4" fill="#c5b4e5"/><g transform="translate(122 172) rotate(-12)"><rect x="0" y="20" width="278" height="123" rx="23" fill="#584194"/><rect x="0" y="5" width="278" height="123" rx="23" fill="url(#platform)"/><path d="M26 102h130" stroke="#c6b5e5" stroke-width="1" opacity=".55"/><rect x="27" y="38" width="172" height="36" rx="10" fill="#493580"/><rect x="35" y="43" width="155" height="14" rx="5" fill="#2c2055"/><circle cx="235" cy="53" r="14" fill="#eccc64"/><circle cx="235" cy="53" r="6" fill="#f4e09b"/><circle cx="222" cy="91" r="4" fill="#bde2ca"/><circle cx="236" cy="91" r="4" fill="#c3b6e0"/><text x="27" y="116" font-size="8" letter-spacing="3" fill="#e4dcf7" font-family="monospace">LANGUAGE / LAB</text></g><g class="art-float"><g transform="translate(194 71) rotate(-12)" filter="url(#ds)"><rect x="8" y="12" width="143" height="145" rx="16" fill="#ae9dd1"/><rect x="0" y="0" width="143" height="145" rx="16" fill="url(#face)" stroke="#fff" stroke-width="2"/><rect x="15" y="15" width="114" height="84" rx="10" fill="${st.cover}"/><g transform="translate(48 33) scale(2.1)" fill="none" stroke="${st.ink}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${ICONS[st.icon]}</g><text x="17" y="118" font-size="9" letter-spacing="2" fill="#6c588e" font-family="monospace">MODULE ${st.number}</text><path d="M20 133v10m13-10v10m13-10v10m13-10v10m13-10v10m13-10v10m13-10v10m13-10v10" stroke="#d2ae4e" stroke-width="6"/></g></g><g class="art-float2"><g transform="translate(389 184) rotate(12)"><rect x="5" y="7" width="75" height="74" rx="14" fill="#dac8a0"/><rect width="75" height="74" rx="14" fill="#f5d16a"/><path d="m23 36 10 10 20-23" fill="none" stroke="#8b693c" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></g><g transform="translate(96 117) rotate(-13)"><rect x="3" y="5" width="59" height="59" rx="12" fill="#b8a6cc"/><rect width="59" height="59" rx="12" fill="#e1d8f0"/><text x="29.5" y="39" text-anchor="middle" fill="#8c72b4" font-size="29" font-weight="800">文</text></g></g><path d="M385 66v16m-8-8h16M92 208v12m-6-6h12" stroke="#cda951" stroke-width="2" stroke-linecap="round"/><circle cx="396" cy="306" r="3" fill="#ae94d4"/><circle cx="142" cy="78" r="3" fill="#d4b15d"/></svg>`}
function mastery(pid=DB.active){let best={};DB.records.filter(g=>g.playerId===pid&&!g.classroom).forEach(g=>Object.values(g.outcomes).forEach(r=>{if(r.status==='correct')best[r.qid]=Math.max(best[r.qid]||0,r.points||0)}));return best}
function home(){stopClock();S.screen='home';S.game=null;S.eliminate=false;const st=STAGES.find(x=>x.id===S.stage)||STAGES[0],best=mastery(),active=DB.activeGames[DB.active];mount(`<main class="fade-in"><div class="home-intro"><p class="eyebrow">6E / 任務選擇</p><div class="home-stats"><span>已接通<b>${Object.keys(best).length}<span class="muted"> / 35</span></b></span><span>累積能量<b>${Object.values(best).reduce((a,b)=>a+b,0)}</b></span></div></div><section class="hero" id="hero"><div class="hero-copy"><div class="hero-tag">${st.id==='mixed'?'本節推薦':`MODULE ${st.number}`} · ${esc(st.title)}</div><h1>${st.headline}</h1><p>${esc(st.desc)}</p><div class="hero-detail"><span>${icon('blocks')}${st.qids.length}題</span><span>${icon(st.id==='mixed'?'clock':st.icon)}${esc(st.minutes)}</span></div><div class="button-row"><button class="btn primary" data-action="start" data-stage="${st.id}">啟動任務 ${icon('arrow')}</button><button class="btn subtle" data-action="help">怎樣玩？</button></div></div><div class="hero-art">${heroArt(st)}<span class="hero-caption">OBSERVE · CONNECT · DISCOVER</span></div><span class="hero-number" aria-hidden="true">${st.number}</span></section>${active&&!active.finished?`<div class="resume-bar"><p><b>上次的任務還在。</b> ${esc(active.title)} · 已完成 ${Object.keys(active.outcomes).length}/${active.qids.length} 題</p><button class="btn compact" data-action="resume">繼續 ${icon('arrow')}</button></div>`:''}<div class="carousel-heading"><h2>選一張任務卡帶 <span>5個專題 + 課堂挑戰</span></h2><div class="carousel-nav">${iconButton('prevStage','left','上一張卡帶')}${iconButton('nextStage','right','下一張卡帶')}</div></div><div class="cartridges" id="cartridges" aria-label="任務卡帶，可左右捲動">${STAGES.map(x=>{let count=x.qids.filter(id=>best[id]).length;return `<button class="cartridge ${x.id===st.id?'selected':''}" data-action="selectStage" data-stage="${x.id}" aria-pressed="${x.id===st.id}" style="--cover:${x.cover};--coverink:${x.ink}"><div class="cart-cover"><span class="cart-id">${x.number} / ${x.id==='mixed'?'MIX':'LAB'}</span>${icon(x.icon)}<span class="cart-count">${x.qids.length} 題</span></div><div class="cart-body"><strong>${esc(x.title)}</strong><small>${esc(x.sub)}</small><div class="cart-progress"><i style="width:${count/x.qids.length*100}%"></i></div></div></button>`}).join('')}</div><div class="home-bottom"><span>左右滑動選卡帶 · 點選後按「啟動任務」</span><div class="button-row"><button class="textbtn" data-action="records">${icon('history')} 答題紀錄</button><button class="textbtn" data-action="retryWrong">${icon('reset')} 錯題再練</button><button class="textbtn" data-action="teacher">${icon('teacher')} 課堂工具</button><button class="textbtn" data-action="settings">${icon('settings')} 設定</button></div></div></main>`);const rail=$('#cartridges');rail.scrollLeft=S.railScroll||0;rail.addEventListener('scroll',()=>S.railScroll=rail.scrollLeft,{passive:true});}
function selectStage(id,scroll=false){S.stage=id;const railScroll=$('#cartridges')?.scrollLeft||0;S.railScroll=railScroll;home();if(scroll){const item=$(`[data-action="selectStage"][data-stage="${id}"]`);item?.scrollIntoView({behavior:isReduced()?'auto':'smooth',block:'nearest',inline:'center'})}sfx('tap')}
function chooseRelative(n){let i=STAGES.findIndex(x=>x.id===S.stage);selectStage(STAGES[(i+n+STAGES.length)%STAGES.length].id,true)}
function ensureDraft(g,id){if(g.drafts[id])return;let q=Q[id];let order=[];if(q.type==='order'){order=q.items.map(x=>x[0]);for(let i=order.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}if(order.join()===q.answer.join())[order[0],order[1]]=[order[1],order[0]]}g.drafts[id]={selected:[],order,words:[],attempts:0,text:'',marks:{},markTexts:{},hint:false,markMode:false,revealed:false,excluded:[],notice:'',created:Date.now()}}
function requestStart(stageId,customIds=null,customTitle=null){const old=DB.activeGames[DB.active];const spec={stageId,customIds,customTitle};if(old&&!old.finished){S.pendingStart=spec;modal('replace','改開另一項任務？',`<p>「${esc(old.title)}」的未完成進度會被取代。已完成的答題紀錄不會刪除。</p><div class="button-row"><button class="btn primary" data-action="freshStart">開始新任務</button><button class="btn" data-action="resume">繼續原任務</button><button class="btn subtle" data-action="close">取消</button></div>`);return}start(spec)}
function start(spec){closeModal();stopClock();let st=STAGES.find(x=>x.id===spec.stageId)||STAGES[0];let ids=(spec.customIds||st.qids).filter(id=>Q[id]);if(!ids.length){toast('暫時沒有需要練習的題目。');return}const p=profile();let g={id:uid(),title:spec.customTitle||st.title,stageId:spec.stageId,qids:ids,index:0,playerId:p.id,playerName:p.name,classroom:DB.settings.classroom,started:new Date().toISOString(),elapsed:0,drafts:{},outcomes:{},finished:false};ids.forEach(id=>ensureDraft(g,id));DB.activeGames[p.id]=g;S.game=g;S.screen='game';S.mobileTab='question';S.eliminate=false;save();renderGame();startClock();window.scrollTo(0,0);sfx('start')}
function resume(){closeModal();const g=DB.activeGames[DB.active];if(!g||g.finished){home();return}S.game=g;S.screen='game';g.qids.forEach(id=>ensureDraft(g,id));S.mobileTab='question';S.eliminate=false;renderGame();startClock();window.scrollTo(0,0)}
function bodyMarks(text,prefix){let d=draft(),pieces=text.match(/[^，。！？；：、\n]+[，。！？；：、]*|[，。！？；：、]+|\n+/g)||[text];return pieces.map((t,i)=>{let k=`${prefix}-${i}`,match=revealed()&&(EVIDENCE[curId()]||[]).some(e=>t.includes(e));if(!t.trim())return esc(t);return `<span role="button" class="markable ${d.marks[k]?'marked':''} ${match?'evidence':''}" data-action="mark" data-mark="${esc(k)}" tabindex="${d.markMode?0:-1}" aria-pressed="${!!d.marks[k]}" title="${d.markMode?'點選標記線索':'開啟標記模式後，可點選線索'}">${esc(t)}</span>`}).join('')}
function readingHTML(q){let tmp=document.createElement('div');tmp.innerHTML=TEXTS[q.reading].html;let walker=document.createTreeWalker(tmp,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach((n,i)=>{if(!n.textContent.trim())return;let span=document.createElement('span');span.innerHTML=bodyMarks(n.textContent,`${q.reading}-${i}`);n.replaceWith(span)});return tmp.innerHTML}
function renderReading(q){let d=draft();return `<aside class="reading-panel ${S.mobileTab==='reading'?'mobile-visible':''}" aria-label="閱讀材料"><div class="read-head"><div><h3>${esc(TEXTS[q.reading].title)}</h3><small>試卷閱讀材料${q.reading==='driver'?' · 節錄前三段':''}</small></div><div class="read-tools"><button data-action="fontMinus" aria-label="縮小閱讀字體">A−</button><button data-action="fontPlus" aria-label="放大閱讀字體">A+</button><button data-action="markMode" class="${d.markMode?'active':''}" aria-label="${d.markMode?'關閉':'開啟'}線索標記" title="線索標記">${icon('pen')}</button></div></div><div class="reading-text ${d.markMode?'mark-mode':''}" id="readingText">${readingHTML(q)}</div><div class="read-footer"><span>${revealed()?'綠色：解析線索 · 黃色：你的標記':d.markMode?'點選句段，留下你的線索 · 不計分':'開啟筆形按鈕，點選句段標記 · 不計分'}</span><button class="textbtn" data-action="showMarks">標記 ${markCount()}</button></div></aside>`}
function renderContext(q){let d=draft();return `<div class="marktools"><button class="btn ${d.markMode?'active':''}" data-action="markMode">${icon('pen')}${d.markMode?'完成標記':'標記線索'}</button><small>${d.markMode?'點選句段；再按一次可取消':'自己的標記不計分'} · ${markCount()} 處</small></div><div class="context ${curId().startsWith('rh')?'rhet-context':''} ${d.markMode?'mark-mode':''}"><div>${bodyMarks(q.context,'context')}</div></div>`}
function interaction(q){let d=draft(),r=outcome(),lock=!!r;
if(curId().startsWith('rh'))return `<div class="chip-socket ${d.selected.length?'filled':''} ${revealed()&&r?.status==='correct'?'lit':''}" data-drop="rhet">${icon(d.selected.length?'chip':'down')}${d.selected.length?`<strong>${esc(q.options[d.selected[0]])}</strong>`:'<span>拖入修辭卡，或直接點選</span>'}</div><div class="rhet-palette count-${q.options.length}">${q.options.map((t,i)=>`<button class="rhet-chip ${d.selected.includes(i)?'selected':''} ${revealed()&&q.answer===i?'good':''}" data-action="option" data-index="${i}" data-drag="rhet" data-token="${i}" ${lock?'disabled':''} aria-pressed="${d.selected.includes(i)}">${esc(t)}<span class="keyhint">${i+1}</span></button>`).join('')}</div>`;
if(q.type==='single'||q.type==='multi')return `<div class="options-meta"><span>${q.type==='multi'?`請選兩項 <b class="selected-count">${d.selected.length} / ${q.count}</b>`:'請選最合適的答案'}</span><button class="btn compact ${S.eliminate?'active':''}" data-action="eliminate" ${lock?'disabled':''}>${icon('focus')}${S.eliminate?'完成排除':'排除選項'}</button></div><div class="option-grid">${q.options.map((t,i)=>{let cls=d.selected.includes(i)?'selected ':'';if(d.excluded.includes(i))cls+='eliminated ';if(revealed()){let yes=q.type==='multi'?q.answer.includes(i):q.answer===i;cls+=yes?'good ':d.selected.includes(i)?'bad ':''}return `<button class="option ${cls}" data-action="option" data-index="${i}" ${lock?'disabled':''} aria-pressed="${d.selected.includes(i)}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(t)}</span></button>`}).join('')}</div>`;
if(q.type==='order')return `<div class="sort-instruction">${icon('drag')}拖動左側把手；也可按右側箭頭移動。</div><div class="sentence-track" data-drop="sentence">${d.order.map((id,i)=>`<div class="sentence-tile" data-sentence="${id}"><span class="position mono">${i+1}</span><button class="drag-handle" data-drag="sentence" data-token="${id}" aria-label="拖動句子${id}" ${lock?'disabled':''}>${icon('drag')}</button><span class="sentence-text"><span class="sentence-label">${id}</span>${esc(q.items.find(x=>x[0]===id)[1])}</span><div class="tile-arrows"><button data-action="moveSentence" data-token="${id}" data-delta="-1" aria-label="把句子${id}上移" ${lock||i===0?'disabled':''}>${icon('up')}</button><button data-action="moveSentence" data-token="${id}" data-delta="1" aria-label="把句子${id}下移" ${lock||i===d.order.length-1?'disabled':''}>${icon('down')}</button></div></div>`).join('')}</div><div class="sort-actions"><button class="textbtn" data-action="previewOrder">${icon('book')}連起來讀</button></div>`;
if(q.type==='wordorder'){let selected=d.words,bank=q.words.map((t,i)=>i).filter(i=>!selected.includes(i));let chip=(i,where)=>`<button class="word-chip" data-action="word" data-drag="word" data-token="${i}" data-where="${where}" data-word="${i}" ${lock?'disabled':''} title="${where==='track'?'點選移回詞組區；拖動可重排':'點選加入句子；也可拖動'}">${esc(q.words[i])}</button>`;return `<div class="sort-instruction">${icon('blocks')}拖入詞組，或逐個點選。句子中的詞組也可拖動重排。</div><div class="track-header"><span>句子軌道</span><span>${selected.length} / ${q.words.length}</span></div><div class="word-track" data-drop="word">${selected.map(i=>chip(i,'track')).join('')}</div><div class="track-header"><span>待接駁詞組</span></div><div class="word-bank" data-drop="bank">${bank.map(i=>chip(i,'bank')).join('')}${bank.length?'':'<small class="muted">全部詞組已接入句子。</small>'}</div><div class="sort-actions"><button class="textbtn" data-action="previewOrder">${icon('book')}連起來讀</button><button class="textbtn" data-action="undoWord" ${lock||!selected.length?'disabled':''}>撤回最後一個</button><button class="textbtn" data-action="resetWords" ${lock?'disabled':''}>清空重排</button></div>`}
if(q.type==='open')return `<label class="visually-hidden" for="openAnswer">你的祝頌語</label><textarea class="open-answer" id="openAnswer" maxlength="40" placeholder="寫下你想送上的祝福……" ${lock?'disabled':''}>${esc(d.text)}</textarea><div class="open-note">這是開放題。提交後保留答案，交由老師核對；不會只因與示例不同而判錯。</div>`;
return ''}
function answerText(q){if(q.type==='single')return `${String.fromCharCode(65+q.answer)}．${q.options[q.answer]}`;if(q.type==='multi')return q.answer.map(i=>`${String.fromCharCode(65+i)}．${q.options[i]}`).join('；');if(q.type==='order')return q.answer.join(' → ');return q.answer.join('／')}
function debriefDiagram(id){let flow=null;if(id==='wt1')flow=['花圃','健康徑','野餐點','吊橋','水上樂園'];if(id==='wt2')flow=['從前 · 家鄉','三年前 · 南京','如今 · 海上'];if(id==='core3')flow=['從前','知道以後','沒想到','自此'];if(id==='extra3')flow=['決定洗碗','收拾餐具','媽媽指導','清洗','沖水抹乾'];if(flow)return `<div class="evidence-map">${flow.map((s,i)=>`${i?'<span class="map-arrow">→</span>':''}<span>${esc(s)}</span>`).join('')}</div>`;if(id==='wt3')return '<div class="evidence-columns"><div><b>航空駕駛</b>高空飛行，倚靠儀器判斷。</div><div><b>地面駕駛</b>路況、行人及車輛變化更多。</div></div>';if(id==='wt4')return '<div class="evidence-columns"><div><b>視覺</b>蔚藍、蒼翠、雲海、白雪。</div><div><b>觸覺</b>和煦的陽光、清爽的秋風、凜冽的寒風。</div></div>';if(id==='wt5')return '<div class="evidence-map"><span>登山與景色</span><span class="map-arrow">→</span><span>「你是多麼慷慨」</span><span class="map-arrow">→</span><span>喜愛之情</span></div>';return ''}
function feedbackHTML(){let q=curQ(),d=draft(),r=outcome();if(!r){if(d.notice||d.hint)return `<section class="feedback retry" id="feedback" tabindex="-1" aria-live="polite"><h3>${icon('light')}${d.attempts?'再看一次線索':'給你一個方向'}</h3><p>${esc(d.notice||q.tip)}</p></section>`;return ''}let label={correct:r.attempts===1?'接通了！':'成功接通！',wrong:'看看哪裏斷了線',pending:'已保存，等待核對',skipped:'留待課堂討論'}[r.status],cls={correct:'good',wrong:'wrong',pending:'pending',skipped:''}[r.status];let body='';if(!revealed()){body=`<p>${r.status==='pending'?'答案已保留，老師可在答題紀錄核對。':'先說說你的判斷依據，再揭曉解析。'}</p><button class="btn compact" data-action="reveal">${icon('eye')}揭曉參考答案</button>`}else{body=`${r.status==='pending'?`<p>${q.type==='open'?'開放題不自動評分。':'這個排序未匹配原卷參考句式，暫不自動判錯，請老師核對。'}</p>`:''}<p class="answer">${q.type==='wordorder'?'原卷參考句式':'參考答案'}：${esc(answerText(q))}</p><div class="explain-label">解題線索 · 教學提示</div><p>${esc(q.explain)}</p>${debriefDiagram(curId())}`;if(q.type==='wordorder')body+='<p style="font-size:12px">自動核對只採用原卷參考句式；其他通順句式可請老師覆核。</p>';if(r.status==='pending'&&DB.settings.classroom)body+=`<div class="manual-buttons"><button class="btn compact" data-action="gradeCurrent" data-verdict="correct">老師確認：合理</button><button class="btn compact" data-action="gradeCurrent" data-verdict="wrong">老師確認：再練</button></div>`}return `<section class="feedback ${cls}" id="feedback" tabindex="-1" aria-live="polite"><h3>${icon(r.status==='correct'?'check':r.status==='pending'?'clock':'light')}${label}${r.points?`<span class="points">+${r.points}</span>`:''}</h3>${body}</section>`}
function ready(){let q=curQ(),d=draft();if(!q)return false;if(outcome())return true;if(q.type==='single')return d.selected.length===1;if(q.type==='multi')return d.selected.length===q.count;if(q.type==='order')return d.order.length===q.items.length;if(q.type==='wordorder')return d.words.length===q.words.length;if(q.type==='open')return d.text.trim().length>=2;return false}
function renderGame(keep=false){if(!S.game)return;const oldRead=$('#readingText')?.scrollTop||0,oldScroll=window.scrollY,oldId=$('#app').dataset.qid;S.screen='game';let g=S.game,id=curId(),q=curQ(),d=draft(),r=outcome();let n=Object.keys(g.outcomes).length,streak=0;for(let i=g.index;i>=0;i--){const o=g.outcomes[g.qids[i]];if(o?.status==='correct'&&o.attempts===1)streak++;else if(i!==g.index)break}mount(`<main class="${keep?'':'fade-in'}">${DB.settings.classroom?`<div class="teacher-bar"><span>${icon('teacher')} 課堂共答 · ${DB.settings.manualReveal?'由老師揭曉解析':'即時顯示解析'}</span><div class="button-row"><button class="textbtn" data-action="teacher">選題／工具</button><button class="textbtn" data-action="skip">跳過本題</button></div></div>`:''}<div class="gamebar"><div class="game-title">${iconButton('pause','left','暫停及返回')}<div><h2>${esc(g.title)}</h2><small>任務 ${String(g.index+1).padStart(2,'0')} / ${String(g.qids.length).padStart(2,'0')} · ${esc(q.tag)}</small></div></div><div class="game-metrics">${streak>=2?`<span class="streak-pill">${icon('bolt')}${streak}題連續接通</span>`:''}<span class="mono"><span class="time-label">${icon('clock')} </span><b id="clock">${fmt(timeNow())}</b></span><span>能量 <b class="score-val mono">${score(g)}</b></span>${iconButton('pause','pause','暫停')}</div></div><div class="progress" aria-label="已完成${n}題，共${g.qids.length}題">${g.qids.map((x,i)=>{let o=g.outcomes[x];return `<button class="${i===g.index?'current ':''}${o?o.status==='correct'?'done':o.status==='pending'?'pending':o.status==='wrong'?'wrong':'':''} ${DB.settings.classroom?'teacher-step':''}" ${DB.settings.classroom?`data-action="jump" data-index="${i}"`:'tabindex="-1"'} aria-label="第${i+1}題${o?'，已處理':''}"></button>`}).join('')}</div>${q.reading?`<nav class="mobile-tabs" aria-label="閱讀與答題切換"><button class="${S.mobileTab==='question'?'active':''}" data-action="mobileTab" data-tab="question">題目與作答</button><button class="${S.mobileTab==='reading'?'active':''}" data-action="mobileTab" data-tab="reading">${icon('book')}閱讀材料${markCount()?` · ${markCount()}處標記`:''}</button></nav>`:''}<div class="game-shell ${q.reading?'with-reading':''} ${id.startsWith('rh')?'rhet-lab':''}">${q.reading?renderReading(q):''}<section class="workspace ${q.reading&&S.mobileTab==='reading'?'mobile-hidden':''}"><div class="work-header"><span class="tag">${icon(id.startsWith('rh')?'chip':q.type==='wordorder'||q.type==='order'?'blocks':q.reading?'book':'focus')}${esc(q.tag)}</span><span class="eyebrow">OBSERVE / CONNECT</span>${iconButton('source','info','查看試題來源')}</div><div class="task-body"><h1>${esc(q.title)}</h1>${q.context?renderContext(q):''}${interaction(q)}${feedbackHTML()}</div><div class="actionbar"><div class="action-left">${r?`<small class="muted">${r.status==='pending'?'待老師核對':r.status==='skipped'?'本題未計分':'本題已記錄'}</small>`:`<span class="attempts" aria-label="第${d.attempts+1}次作答"><i class="${d.attempts>0?'used':''}"></i><i></i></span><button class="textbtn" data-action="hint">${icon('light')}提示</button>`}</div><button class="btn primary" id="confirm" data-action="${r?'next':'submit'}" ${ready()?'':'disabled'}>${r?(g.index===g.qids.length-1?'完成任務':'下一題'):(q.type==='open'?'保存答案':id.startsWith('rh')?'啟動分析':'確認接駁')} ${icon('arrow')}</button></div></section></div></main>`);$('#app').dataset.qid=id;if(q.reading&&oldId===id&&keep&&$('#readingText'))$('#readingText').scrollTop=oldRead;if(keep)window.scrollTo(0,oldScroll);if(S.readSize)$('#readingText')?.style.setProperty('--reading',`${S.readSize}px`);save()}
function focusFeedback(){let f=$('#feedback');if(f){f.focus({preventScroll:true});f.scrollIntoView({behavior:isReduced()?'auto':'smooth',block:'nearest'})}}
function norm(s){return String(s).replace(/[\s\u200b]/g,'').replace(/[﹐,]/g,'，').replace(/[﹒.]/g,'。')}
function responseText(q,d){if(q.type==='single'||q.type==='multi')return d.selected.map(i=>`${String.fromCharCode(65+i)}．${q.options[i]}`).join('；');if(q.type==='order')return d.order.join(' → ');if(q.type==='wordorder')return d.words.map(i=>q.words[i]).join('');return d.text.trim()}
function makeOutcome(status,points,by='automatic'){const q=curQ(),d=draft();S.game.outcomes[curId()]={qid:curId(),status,points,attempts:d.attempts,response:responseText(q,d),hints:d.hint,marks:Object.values(d.markTexts),source:q.source,by,answered:new Date().toISOString()};save()}
function submit(){if(outcome()||!ready())return;const q=curQ(),d=draft();d.attempts++;if(q.type==='open'){makeOutcome('pending',null,'pending');renderGame(true);focusFeedback();return}let good=false;if(q.type==='single')good=d.selected[0]===q.answer;if(q.type==='multi')good=[...d.selected].sort().join() === [...q.answer].sort().join();if(q.type==='order')good=d.order.join()===q.answer.join();if(q.type==='wordorder')good=q.answer.some(a=>norm(a)===norm(d.words.map(i=>q.words[i]).join('')));if(good){makeOutcome('correct',d.attempts===1?100:60);sfx('correct');renderGame(true);celebrate();let consecutive=0;for(let i=S.game.index;i>=0;i--){let o=S.game.outcomes[S.game.qids[i]];if(o?.status==='correct'&&o.attempts===1)consecutive++;else break}if(consecutive===3||consecutive===5)achievement(`${consecutive}題連續接通`)}else if(d.attempts===1){d.notice=q.tip;sfx('retry');renderGame(true)}else{makeOutcome(q.type==='wordorder'?'pending':'wrong',q.type==='wordorder'?null:0,q.type==='wordorder'?'pending':'automatic');sfx('retry');renderGame(true)}focusFeedback()}
function chooseOption(i){if(outcome())return;const q=curQ(),d=draft();if(S.eliminate&&!curId().startsWith('rh')){if(d.excluded.includes(i))d.excluded=d.excluded.filter(x=>x!==i);else{d.excluded.push(i);d.selected=d.selected.filter(x=>x!==i)}}else{d.excluded=d.excluded.filter(x=>x!==i);if(q.type==='single')d.selected=[i];else if(d.selected.includes(i))d.selected=d.selected.filter(x=>x!==i);else if(d.selected.length<q.count)d.selected.push(i);else{toast(`這題選${q.count}項；先取消其中一項再更換。`);return}}sfx('tap');renderGame(true)}
function next(){if(!outcome())return;stopClock();if(S.game.index<S.game.qids.length-1){S.game.index++;S.eliminate=false;S.mobileTab='question';renderGame();window.scrollTo(0,0);startClock();sfx('tap')}else finish()}
function jump(index){if(!DB.settings.classroom||!S.game)return;stopClock();S.game.index=Math.max(0,Math.min(index,S.game.qids.length-1));S.mobileTab='question';S.eliminate=false;closeModal();renderGame();startClock();window.scrollTo(0,0)}
function skip(){if(!DB.settings.classroom)return;if(!outcome()){draft().revealed=false;makeOutcome('skipped',null,'teacher')}next()}
function moveSentence(id,delta){if(outcome())return;let a=draft().order,i=a.indexOf(id),j=i+delta;if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];sfx('tap');renderGame(true)}
function tapWord(i){if(outcome())return;let d=draft();if(d.words.includes(i))d.words=d.words.filter(x=>x!==i);else d.words.push(i);sfx('tap');renderGame(true)}
function reveal(){if(!outcome())return;draft().revealed=true;renderGame(true);focusFeedback()}
function gradeCurrent(verdict){if(!DB.settings.classroom)return;let r=outcome();if(r?.status!=='pending')return;r.status=verdict;r.points=verdict==='correct'?(r.attempts>1?60:100):0;r.by='teacher';save();renderGame(true)}
function finish(){stopClock();let g=S.game;S.screen='finish';if(!g.finished){g.finished=true;g.ended=new Date().toISOString();DB.records.push(g);delete DB.activeGames[g.playerId];save()}renderFinish();sfx('finish');celebrate()}
function renderFinish(){let g=S.game;if(!g)return;let rs=Object.values(g.outcomes),gg=graded(g),correct=rs.filter(r=>r.status==='correct').length,first=rs.filter(r=>r.status==='correct'&&r.attempts===1).length,pending=rs.filter(r=>r.status==='pending').length,unanswered=g.qids.length-rs.length+rs.filter(r=>r.status==='skipped').length;let byTag={};g.qids.forEach(id=>{let tag=Q[id].tag;if(!byTag[tag])byTag[tag]={correct:0,total:0};let r=g.outcomes[id];if(r?.status==='correct'||r?.status==='wrong'){byTag[tag].total++;if(r.status==='correct')byTag[tag].correct++}});let weaknesses=Object.entries(byTag).filter(([k,v])=>v.total&&v.correct<v.total).map(([k])=>k);mount(`<main class="fade-in"><section class="finish-card"><div class="finish-heading"><div class="finish-badge">${icon('trophy')}</div><div><p class="eyebrow" style="color:var(--purple);margin-bottom:6px">MISSION COMPLETE</p><h1>這次任務，完成。</h1><p>${esc(g.title)} · ${esc(g.playerName)}${g.classroom?' · 課堂共答':''}</p></div><div class="finish-score mono">${score(g)}<small>／${gg.length*100} 分${pending?' · 待核對題未計分':''}${unanswered?' · 未作答題未計分':''}</small></div></div><div class="stat-grid"><div class="stat-box"><b>${correct}<span> / ${gg.length}</span></b><span>已判分題答對</span></div><div class="stat-box"><b>${first}</b><span>首次答對</span></div><div class="stat-box"><b class="mono">${fmt(g.elapsed)}</b><span>實際作答時間</span></div></div>${pending||unanswered?`<div class="teacher-note" style="margin-top:17px;margin-bottom:0">${pending?`${pending} 題待老師核對。`:''}${unanswered?`${unanswered} 題未作答或已跳過。`:''}以上均未納入評分分母，不代表已掌握。</div>`:''}<div class="finish-body"><div>${Object.entries(byTag).map(([k,v])=>`<div class="skill-row"><div><span>${esc(k)}</span><span>${v.total?`${v.correct}/${v.total}`:'待核對'}</span></div><div class="skill-bar"><i style="width:${v.total?v.correct/v.total*100:0}%"></i></div></div>`).join('')}</div><div class="lesson-card"><h3>${weaknesses.length?'下一步，把斷線接好。':'留下你的解題方法。'}</h3><p>${weaknesses.length?`今次先重溫「${esc(weaknesses.join('、'))}」。打開下面的逐題紀錄，看看答案的依據，再試一次。`:'答對之後，試用一句話說出依據。能指出文中的線索，比記住選項更重要。'}${pending?'開放題或其他合理句式，請老師看過後再確認。':''}</p></div></div><div class="button-row"><button class="btn primary" data-action="home">返回任務選單 ${icon('arrow')}</button><button class="btn" data-action="retrySession">${icon('reset')}重練需改善題</button><button class="btn" data-action="exportCurrent">${icon('download')}匯出本次紀錄</button></div><div class="finish-review"><h3>逐題回顧</h3>${g.qids.map((id,i)=>{let q=Q[id],r=g.outcomes[id],visible=!DB.settings.manualReveal||g.drafts[id]?.revealed;return `<details><summary><span class="result-chip ${r?.status||'pending'}">${r?statusLabel(r.status):'未作答'}</span>${i+1}. ${esc(q.tag)}${r?.points?` · +${r.points}`:''}</summary><p>你的答案：${esc(r?.response||'未作答')}${visible?`<br>參考答案：${esc(answerText(q))}<br>${esc(q.explain)}`:'<br>解析尚未揭曉；可由老師在「課堂工具 → 題庫」查看。'}<br><small>${esc(q.source)}</small></p></details>`}).join('')}</div></section></main>`);window.scrollTo(0,0)}
function statusLabel(s){return {correct:'已接通',wrong:'需再練',pending:'待核對',skipped:'已跳過'}[s]||'未作答'}
function latestWrong(){let latest={};DB.records.filter(g=>g.playerId===DB.active&&!g.classroom).forEach(g=>Object.values(g.outcomes).forEach(r=>latest[r.qid]=r));return Object.keys(latest).filter(id=>latest[id].status==='wrong')}
function retryWrong(){let ids=latestWrong();if(!ids.length){toast('暫時沒有已判錯的題目。待核對題可在答題紀錄查看。');return}requestStart('review',ids,'錯題修復任務')}
function retrySession(){let g=S.game;let ids=g.qids.filter(id=>!g.outcomes[id]||g.outcomes[id].status!=='correct');if(!ids.length){toast('本次已判分題全部答對，可返回選另一個專題。');return}requestStart('review',ids,'本次題目再練')}
/* Dialog controls use native modal focus containment. */
function modal(name,title,html,wide=false){stopClock();S.modal=name;S.lastFocus=document.activeElement;const dlg=$('#dialog');dlg.className=wide?'wide':'';dlg.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${iconButton('close','close','關閉')}</div><div class="dialog-body">${html}</div>`;if(!dlg.open)dlg.showModal();}
function closeModal(){const d=$('#dialog');if(d.open)d.close();S.modal=null;startClock()}
function toast(text){$('.mission-toast')?.remove();const e=document.createElement('div');e.className='mission-toast';e.textContent=text;e.setAttribute('role','status');document.body.appendChild(e);setTimeout(()=>e.remove(),3400)}
function pause(){modal('pause','任務已暫停',`<p>進度已保留在這個瀏覽器。暫停期間不會計時。</p><div class="button-row"><button class="btn primary" data-action="close">繼續接駁 ${icon('play')}</button><button class="btn" data-action="saveHome">保存並返回</button><button class="btn subtle" data-action="settings">設定</button></div>`)}
function profileModal(){modal('profile','誰來啟動實驗室？',`<p>選擇本機玩家，或使用暱稱新增。這不是帳戶登入，資料不會上傳。</p><div class="profile-list">${DB.profiles.map(p=>`<button class="profile-item ${p.id===DB.active?'active':''}" data-action="switchProfile" data-profile="${esc(p.id)}"><span class="avatar">${esc(p.name.slice(0,1))}</span>${esc(p.name)}</button>`).join('')}</div><div class="sep"></div><form id="profileForm"><div class="field"><label for="playerName">新增玩家暱稱／學號</label><input id="playerName" maxlength="18" autocomplete="off" placeholder="例如：6E 08"><small>同一裝置可供不同玩家輪流使用；不用輸入真名。</small></div><button class="btn primary" type="submit">使用這個名字 ${icon('arrow')}</button></form>`)}
function switchProfile(id){if(!DB.profiles.some(p=>p.id===id))return;stopClock();DB.active=id;save();closeModal();home();toast(`已切換至 ${profile().name}`)}
function settingsModal(){modal('settings','設定',`${setting('sound','操作音效','預設靜音；由你決定是否開啟。')}${setting('projector','大字展示','適合課室電視；文字較大，可能需要捲動。')}${setting('reduced','減少動畫','關閉浮動、慶祝和過場動畫。')}<div class="sep"></div><p>離線使用，沒有廣告，沒有 API。分數與進度只保存在目前瀏覽器；清除網站資料或換裝置不會自動保留。</p><div class="button-row"><button class="btn" data-action="exportAll">${icon('download')}匯出備份</button><button class="btn" data-action="records">查看答題紀錄</button></div>`)}
function setting(key,label,desc){return `<div class="setting-row"><div><b>${esc(label)}</b><small>${esc(desc)}</small></div><button class="switch ${DB.settings[key]?'on':''}" role="switch" aria-checked="${DB.settings[key]}" aria-label="${esc(label)}" data-action="toggleSetting" data-setting="${key}"></button></div>`}
function help(){modal('help','接駁指南',`<div class="help-block"><h3>修辭卡</h3><p>拖動或點選修辭卡，放進分析槽，再啟動分析。可先開啟「標記線索」，點選句中的片段。</p></div><div class="help-block"><h3>句子與段落</h3><p>詞組可拖入、拖走、插到另一詞組之前；直接點選也可以。段落用左側把手拖排，或按上／下箭頭。</p></div><div class="help-block"><h3>閱讀與解碼</h3><p>閱讀題保留原文。手機用上方頁籤切換材料與作答；筆形按鈕可開啟句段標記。「排除選項」只幫你思考，不會代你評分。</p></div><div class="help-block"><h3>怎樣計分？</h3><p>首次答對100分，第二次60分。第一次答錯只提供提示；第二次才揭曉。提示不扣分，但會記錄曾使用。開放題，以及未匹配原卷參考句式的重組題，會交老師核對。</p></div><div class="help-block"><h3>鍵盤操作</h3><p>主選單：←／→選卡帶，Enter開始。作答：數字1–8選答案，Enter確認，Esc暫停。排序也可用Tab選按鈕、Enter操作。</p></div><div class="teacher-note">35題來自你提供的試卷與原題庫。提示、解析圖及遊戲記分屬教學改編，不等同原卷分數。課堂工具不是密碼鎖；本版本不適合用作保密考試。</div>`)}
function sourceModal(){let q=curQ();if(!q)return;modal('source','這一題從哪裏來？',`<p class="question-summary">${esc(q.title)}</p><div class="source-info"><b>${esc(q.source)}</b><br>題目、選項及參考答案沿用已整理題庫；操作方式、提示及解析圖為教學改編。${curId()==='core6'?'<br>祝頌語「生活愉快」見補考卷；「身體健康」亦見同年正卷。其他合理答案由老師判斷。':''}${q.type==='wordorder'?'<br>原卷接受通順合理的句子。此離線版只自動核對已列出的參考句式；其他句式交老師覆核。':''}${q.reading==='driver'?'<br>閱讀材料保留原卷前三段，包含本題需要的完整第二段。':''}<br>實用文保留上款、祝頌語與下款位置；不把格式改成一般連續段落。</div>`)}
function showMarks(){let d=draft();modal('marks','我的線索標記',`<p>這些是你自行選的線索，不代表系統已判定正確，也不另外計分。</p>${Object.values(d.markTexts).length?Object.values(d.markTexts).map(t=>`<p class="question-summary">${esc(t)}</p>`).join(''):'<div class="empty">開啟筆形按鈕，再點選材料中的句段。</div>'}<button class="btn" data-action="clearMarks">清除本題標記</button>`)}
function teacher(){let tab=S.teacherTab;modal('teacher','課堂工具',`<div class="teacher-note">供老師共答及核對使用，並非帳戶後台或保安鎖。這裏只能看到本機紀錄，或你手動匯入的紀錄。</div><div class="tablist"><button class="${tab==='controls'?'active':''}" data-action="teacherTab" data-tab="controls">課堂控制</button><button class="${tab==='bank'?'active':''}" data-action="teacherTab" data-tab="bank">35題題庫</button><button class="${tab==='records'?'active':''}" data-action="teacherTab" data-tab="records">答題紀錄</button></div>${tab==='controls'?teacherControls():tab==='bank'?teacherBank():recordsHTML(true)}`,true)}
function teacherControls(){return `${setting('classroom','課堂共答模式','顯示跳題、選題與人工核對按鈕；成績標示為課堂共答。')}${setting('manualReveal','先討論，再揭曉解析','題目完成後暫時隱藏答案與說明，再按揭曉。')}${setting('projector','大字展示','適合課室電視。')}<div class="sep"></div><div class="help-block"><h3>本節安排</h3><p>「課堂混合挑戰」沿用8題精選，與35題題庫重複，不另加新題。30分鐘是課堂編排建議，不設倒數壓力。</p></div>${S.game&&S.screen==='game'?`<div class="field"><label for="jumpQuestion">跳到本次任務中的題目</label><select id="jumpQuestion">${S.game.qids.map((id,i)=>`<option value="${i}" ${i===S.game.index?'selected':''}>${i+1}. ${esc(Q[id].tag)} — ${esc((Q[id].context||Q[id].title).slice(0,30))}</option>`).join('')}</select></div><div class="button-row"><button class="btn primary" data-action="jumpSelect">跳到這題</button><button class="btn" data-action="teacherReveal">揭曉目前一題</button></div>`:''}<div class="sep"></div><button class="btn" data-action="teacherTab" data-tab="bank">按範疇選題 ${icon('arrow')}</button>`}
function teacherBank(){return STAGES.filter(s=>s.id!=='mixed').map(st=>`<div class="bank-group"><h3>${esc(st.title)} · ${st.qids.length}題</h3>${st.qids.map(id=>`<div class="question-row"><div>${esc((Q[id].context||Q[id].title).slice(0,58))}${(Q[id].context||Q[id].title).length>58?'…':''}<small>${esc(Q[id].source)}</small></div><button class="btn compact" data-action="inspectQ" data-qid="${id}">檢視</button><button class="btn compact" data-action="singleQ" data-qid="${id}">練這題</button></div>`).join('')}</div>`).join('')}
function inspectQ(id){let q=Q[id];modal('inspect','試題與參考答案',`<span class="tag">${esc(q.tag)}</span><p class="question-summary">${esc(q.context||q.title)}</p>${q.context?`<p>${esc(q.title)}</p>`:''}<p><b>參考答案：</b>${esc(answerText(q))}</p><p>${esc(q.explain)}</p><p class="source-info">${esc(q.source)}<br>解析為教學提示；判分以提供的原卷參考答案為基礎。</p><div class="button-row"><button class="btn primary" data-action="singleQ" data-qid="${id}">開啟這題</button><button class="btn" data-action="teacher">返回題庫</button></div>`)}
function recordsHTML(all=false){let list=DB.records.filter(g=>all||g.playerId===DB.active).slice().reverse();return `<div class="button-row" style="margin-bottom:18px"><button class="btn compact" data-action="exportCSV">${icon('download')}匯出CSV</button><button class="btn compact" data-action="exportAll">${icon('download')}備份JSON</button><button class="btn compact" data-action="import">${icon('upload')}匯入紀錄</button></div><p class="source-info">${all?'本機所有玩家':'目前玩家'} · 共${list.length}次任務。逐題記錄作答、次數、提示、線索及人工核對狀態；沒有雲端同步。</p>${list.length?list.map(g=>`<article class="record-card"><div class="record-top"><div><b>${esc(g.title)}</b><small>${esc(g.playerName)} · ${niceDate(g.ended||g.started)}${g.classroom?' · 課堂共答':''}</small></div><div class="record-score mono">${score(g)} / ${graded(g).length*100}</div></div><details><summary>展開逐題紀錄 · ${Object.keys(g.outcomes).length}/${g.qids.length}題已處理</summary>${g.qids.map(id=>{let r=g.outcomes[id];return `<div class="record-q"><b>${esc(Q[id].tag)} · ${r?statusLabel(r.status):'未作答'}</b><small> · ${r?.attempts||0}次 · ${r?.hints?'用過提示':'未用提示'}</small><div class="record-input">${esc(r?.response||'未作答')}</div>${r?.marks?.length?`<small>學生標記：${esc(r.marks.join(' ／ '))}</small>`:''}${r?.status==='pending'&&all?`<div class="manual-buttons"><button class="btn compact" data-action="gradeRecord" data-record="${esc(g.id)}" data-qid="${id}" data-verdict="correct">老師核對：合理</button><button class="btn compact" data-action="gradeRecord" data-record="${esc(g.id)}" data-qid="${id}" data-verdict="wrong">老師核對：再練</button><button class="btn compact" data-action="inspectQ" data-qid="${id}">看參考答案</button></div>`:''}</div>`}).join('')}</details></article>`).join(''):'<div class="empty">完成一個任務後，紀錄會出現在這裏。</div>'}`}
function records(){modal('records','答題紀錄',recordsHTML(false),true)}
function gradeRecord(record,qid,verdict){let g=DB.records.find(x=>x.id===record),r=g?.outcomes[qid];if(!r||r.status!=='pending')return;r.status=verdict;r.points=verdict==='correct'?(r.attempts>1?60:100):0;r.by='teacher';save();teacher();toast('已更新人工核對結果。')}
function saveFile(name,text,type){let blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000)}
function exportAll(){let obj={format:'6e-language-lab/v2',exported:new Date().toISOString(),profiles:DB.profiles,records:DB.records,activeGames:DB.activeGames};saveFile('6E_語文實驗室_紀錄備份.json',JSON.stringify(obj,null,2),'application/json');toast('已匯出本機紀錄與未完成進度。')}
function exportCurrent(){if(!S.game)return;let obj={format:'6e-language-lab/v2',exported:new Date().toISOString(),profiles:[{id:S.game.playerId,name:S.game.playerName}],records:[S.game],activeGames:{}};saveFile(`6E_${S.game.playerName.replace(/[^\u4e00-\u9fff\w-]/g,'_')}_本次紀錄.json`,JSON.stringify(obj,null,2),'application/json')}
function csvCell(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportCSV(){let all=S.modal==='teacher',list=DB.records.filter(g=>all||g.playerId===DB.active);let rows=[['任務ID','玩家','任務','模式','開始時間','完成時間','實際秒數','題目ID','範疇','原卷出處','作答','狀態','分數','作答次數','曾用提示','評定方式','學生標記']];list.forEach(g=>g.qids.forEach(id=>{let r=g.outcomes[id];rows.push([g.id,g.playerName,g.title,g.classroom?'課堂共答':'個人練習',g.started,g.ended||'',Math.round(g.elapsed),id,Q[id].tag,Q[id].source,r?.response||'',r?statusLabel(r.status):'未作答',r?.points??'',r?.attempts||0,r?.hints?'是':'否',r?.by||'',r?.marks?.join(' ／ ')||''])}));saveFile('6E_語文實驗室_逐題紀錄.csv','\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function validRecord(g){return !!(g&&typeof g.id==='string'&&g.id.length<150&&typeof g.playerId==='string'&&!['__proto__','constructor','prototype'].includes(g.playerId)&&typeof g.playerName==='string'&&typeof g.title==='string'&&Array.isArray(g.qids)&&g.qids.length<=100&&g.qids.every(id=>Object.prototype.hasOwnProperty.call(Q,id))&&g.outcomes&&typeof g.outcomes==='object'&&Object.values(g.outcomes).every(r=>r&&Q[r.qid]&&['correct','wrong','pending','skipped'].includes(r.status)&&typeof r.response==='string'&&r.response.length<20000)&&Number.isFinite(g.elapsed)&&g.elapsed>=0)}
async function importData(file){if(!file)return;if(file.size>5*1024*1024){toast('檔案太大，請使用5MB以下的遊戲JSON備份。');return}try{let d=JSON.parse(await file.text());if(d.format!=='6e-language-lab/v2'||!Array.isArray(d.records))throw Error('format');if(d.records.length>3000||!d.records.every(validRecord))throw Error('record');let added=0;for(const g of d.records){if(!DB.records.some(x=>x.id===g.id)){g.drafts=g.drafts||{};g.qids.forEach(id=>ensureDraft(g,id));DB.records.push(g);added++;if(!DB.profiles.some(p=>p.id===g.playerId))DB.profiles.push({id:g.playerId,name:g.playerName.slice(0,18)})}}let recovered=0;if(d.activeGames&&typeof d.activeGames==='object'){Object.values(d.activeGames).forEach(g=>{if(validRecord(g)&&!g.finished&&!DB.activeGames[g.playerId]){g.drafts=g.drafts||{};g.qids.forEach(id=>ensureDraft(g,id));DB.activeGames[g.playerId]=g;if(!DB.profiles.some(p=>p.id===g.playerId))DB.profiles.push({id:g.playerId,name:g.playerName.slice(0,18)});recovered++}})}save();if(S.modal==='teacher')teacher();else records();toast(`已加入${added}份紀錄${recovered?`及${recovered}個未完成任務`:''}；重複紀錄不覆蓋本機核對結果。`)}catch{toast('未能讀取。請選擇由這個遊戲匯出的JSON備份。')}}
/* Sound is generated locally and only starts after an explicit user gesture. */
let audio;
function sfx(kind){if(!DB.settings.sound)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();let notes={tap:[620],correct:[520,660,880],retry:[330,285],start:[390,520,780],finish:[520,650,780,1040]}[kind]||[620];notes.forEach((hz,i)=>{let o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.075;o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+.14);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.16)})}catch{DB.settings.sound=false;save()}}
function celebrate(){if(isReduced())return;let target=$('#confirm')||$('.finish-badge'),r=target?.getBoundingClientRect();if(!r)return;for(let i=0;i<16;i++){let p=document.createElement('span');p.className='particle';p.style.left=(r.x+r.width/2)+'px';p.style.top=(r.y+10)+'px';p.style.background=['#f7c94e','#8a72d2','#9bbdaa'][i%3];p.style.setProperty('--dx',(Math.random()-.5)*340+'px');p.style.setProperty('--dy',(-50-Math.random()*175)+'px');p.style.animationDelay=Math.random()*.08+'s';document.body.appendChild(p);setTimeout(()=>p.remove(),1100)}}
function achievement(text){if(isReduced())return;const a=document.createElement('div');a.className='achievement-pop';a.textContent='✦ '+text;document.body.appendChild(a);setTimeout(()=>a.remove(),1700)}
/* Pointer drag works for mouse, pen and touch; every operation also has a click alternative. */
let drag=null,suppressClickUntil=0;
function clearDragClasses(){$$('.drop-before,.drop-after,.dropzone-active').forEach(el=>{el.classList.remove('drop-before','drop-after','dropzone-active');el.style.boxShadow=''})}
function dragBegin(e){if(S.screen!=='game'||S.modal||outcome()||e.button>0)return;let el=e.target.closest('[data-drag]');if(!el||el.disabled)return;drag={type:el.dataset.drag,token:el.dataset.token,where:el.dataset.where,el,source:el.dataset.drag==='sentence'?el.closest('.sentence-tile'):el,x:e.clientX,y:e.clientY,active:false,pointer:e.pointerId,ghost:null};}
function dragMove(e){if(!drag||e.pointerId!==drag.pointer)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.active&&Math.hypot(dx,dy)<8)return;if(!drag.active){drag.active=true;const box=drag.source.getBoundingClientRect();drag.ghost=drag.source.cloneNode(true);drag.ghost.classList.add('drag-ghost');drag.ghost.style.width=Math.min(box.width,520)+'px';drag.ghost.style.height=box.height+'px';drag.ghost.removeAttribute('id');document.body.appendChild(drag.ghost);drag.source.classList.add('drag-source');drag.offX=Math.min(e.clientX-box.x,box.width/2);drag.offY=Math.min(e.clientY-box.y,box.height/2)}e.preventDefault();drag.ghost.style.left=(e.clientX-drag.offX)+'px';drag.ghost.style.top=(e.clientY-drag.offY)+'px';clearDragClasses();let hit=document.elementFromPoint(e.clientX,e.clientY);if(drag.type==='rhet'){hit?.closest('[data-drop="rhet"]')?.classList.add('dropzone-active')}else if(drag.type==='sentence'){let tile=hit?.closest('[data-sentence]');if(tile&&tile.dataset.sentence!==drag.token){let r=tile.getBoundingClientRect();tile.classList.add(e.clientY>r.top+r.height/2?'drop-after':'drop-before')}}else if(drag.type==='word'){let zone=hit?.closest('[data-drop]');if(zone&&['word','bank'].includes(zone.dataset.drop)){zone.classList.add('dropzone-active');let chip=hit?.closest('[data-word]');if(chip&&zone.dataset.drop==='word'){chip.style.boxShadow='-4px 0 0 var(--gold)';chip.classList.add('drop-before')}}}if(drag.type!=='rhet'){if(e.clientY>innerHeight-65)window.scrollBy(0,14);else if(e.clientY<90)window.scrollBy(0,-14)}}
function dragEnd(e){if(!drag||e.pointerId!==drag.pointer)return;const dr=drag;drag=null;clearDragClasses();dr.source.classList.remove('drag-source');if(dr.ghost)dr.ghost.remove();if(!dr.active)return;e.preventDefault();suppressClickUntil=Date.now()+450;let hit=document.elementFromPoint(e.clientX,e.clientY),d=draft();if(dr.type==='rhet'){if(hit?.closest('[data-drop="rhet"]'))chooseOption(Number(dr.token))}else if(dr.type==='sentence'){let tile=hit?.closest('[data-sentence]');if(tile&&tile.dataset.sentence!==dr.token){let r=tile.getBoundingClientRect(),after=e.clientY>r.top+r.height/2;d.order=d.order.filter(x=>x!==dr.token);let index=d.order.indexOf(tile.dataset.sentence)+(after?1:0);d.order.splice(index,0,dr.token);renderGame(true);sfx('tap')}}else if(dr.type==='word'){let zone=hit?.closest('[data-drop]');if(zone?.dataset.drop==='bank'){d.words=d.words.filter(x=>x!==Number(dr.token));renderGame(true);sfx('tap')}else if(zone?.dataset.drop==='word'){let chip=hit?.closest('[data-word]'),token=Number(dr.token);if(chip&&Number(chip.dataset.word)===token){renderGame(true);return}d.words=d.words.filter(x=>x!==token);let index=chip?d.words.indexOf(Number(chip.dataset.word)):d.words.length;if(chip){let r=chip.getBoundingClientRect();if(e.clientX>r.left+r.width/2)index++}d.words.splice(Math.max(0,index),0,token);renderGame(true);sfx('tap')}}save()}
function dragCancel(){if(drag){drag.source.classList.remove('drag-source');drag.ghost?.remove();drag=null;clearDragClasses()}}
/* Centralized event routing avoids duplicated listeners after screen updates. */
document.addEventListener('click',e=>{if(Date.now()<suppressClickUntil){e.preventDefault();return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;let a=b.dataset.action,d=S.screen==='game'?draft():null;e.preventDefault();switch(a){
case 'home':closeModal();home();window.scrollTo(0,0);break;
case 'selectStage':selectStage(b.dataset.stage);break;case 'prevStage':chooseRelative(-1);break;case 'nextStage':chooseRelative(1);break;
case 'start':requestStart(b.dataset.stage);break;case 'freshStart':{let spec=S.pendingStart;S.pendingStart=null;start(spec);break}case 'resume':resume();break;
case 'sound':DB.settings.sound=!DB.settings.sound;save();if(S.screen==='game')renderGame(true);else if(S.screen==='finish')renderFinish();else home();sfx('tap');break;
case 'fullscreen':{let el=document.documentElement;if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});else if(el.requestFullscreen)el.requestFullscreen().catch(()=>toast('此瀏覽器不支援全螢幕；可使用大字展示。'));else toast('此瀏覽器不支援全螢幕；可使用大字展示。');break}
case 'settings':settingsModal();break;case 'help':help();break;case 'profile':profileModal();break;case 'switchProfile':switchProfile(b.dataset.profile);break;
case 'close':closeModal();break;case 'pause':pause();break;case 'saveHome':closeModal();home();break;case 'source':sourceModal();break;
case 'option':chooseOption(Number(b.dataset.index));break;case 'eliminate':S.eliminate=!S.eliminate;renderGame(true);break;
case 'markMode':d.markMode=!d.markMode;renderGame(true);break;
case 'mark':if(d?.markMode){const k=b.dataset.mark;if(d.marks[k]){delete d.marks[k];delete d.markTexts[k]}else{d.marks[k]=true;d.markTexts[k]=b.textContent}renderGame(true)}break;
case 'showMarks':showMarks();break;case 'clearMarks':d.marks={};d.markTexts={};closeModal();renderGame(true);break;
case 'fontPlus':S.readSize=Math.min(30,(S.readSize||19)+2);$('#readingText')?.style.setProperty('--reading',S.readSize+'px');break;
case 'fontMinus':S.readSize=Math.max(16,(S.readSize||19)-2);$('#readingText')?.style.setProperty('--reading',S.readSize+'px');break;
case 'mobileTab':S.mobileTab=b.dataset.tab;renderGame(true);break;
case 'moveSentence':moveSentence(b.dataset.token,Number(b.dataset.delta));break;case 'word':tapWord(Number(b.dataset.token));break;
case 'undoWord':if(!outcome()){d.words.pop();renderGame(true)}break;case 'resetWords':if(!outcome()){d.words=[];renderGame(true)}break;
case 'previewOrder':{let q=curQ(),t=q.type==='order'?d.order.map(id=>q.items.find(x=>x[0]===id)[1]).join('。')+'。':d.words.map(i=>q.words[i]).join('');modal('preview','把你的答案連起來讀',`<p class="question-summary">${esc(t||'先把詞組放進句子軌道。')}</p><p>讀一次，檢查語意是否通順。這裏展示的是你的排列，不是參考答案。</p><button class="btn primary" data-action="close">返回組裝</button>`);break}
case 'hint':d.hint=true;d.notice=curQ().tip;renderGame(true);focusFeedback();break;case 'submit':submit();break;case 'next':next();break;case 'reveal':reveal();break;
case 'teacher':teacher();break;case 'teacherTab':S.teacherTab=b.dataset.tab;teacher();break;
case 'toggleSetting':{let key=b.dataset.setting;if(!(key in DEFAULT_SETTINGS))break;DB.settings[key]=!DB.settings[key];if(key==='classroom'&&S.game&&!S.game.finished)S.game.classroom=DB.settings.classroom;save();applySettings();if(S.screen==='game')renderGame(true);if(S.modal==='teacher')teacher();else settingsModal();sfx('tap');break}
case 'jump':jump(Number(b.dataset.index));break;case 'jumpSelect':DB.settings.classroom=true;if(S.game)S.game.classroom=true;jump(Number($('#jumpQuestion').value));break;
case 'skip':skip();break;
case 'teacherReveal':DB.settings.classroom=true;if(!outcome())makeOutcome('skipped',null,'teacher');d.revealed=true;closeModal();renderGame(true);focusFeedback();break;
case 'inspectQ':inspectQ(b.dataset.qid);break;case 'singleQ':closeModal();requestStart('single',[b.dataset.qid],`${Q[b.dataset.qid].tag} · 單題練習`);break;
case 'records':records();break;case 'gradeCurrent':gradeCurrent(b.dataset.verdict);break;case 'gradeRecord':gradeRecord(b.dataset.record,b.dataset.qid,b.dataset.verdict);break;
case 'retryWrong':retryWrong();break;case 'retrySession':retrySession();break;
case 'exportAll':stopClock();exportAll();startClock();break;case 'exportCSV':exportCSV();break;case 'exportCurrent':exportCurrent();break;case 'import':$('#importFile').value='';$('#importFile').click();break;
}});
document.addEventListener('submit',e=>{if(e.target.id!=='profileForm')return;e.preventDefault();const name=$('#playerName').value.trim();if(!name){toast('請先輸入暱稱或學號。');return}let existing=DB.profiles.find(p=>p.name===name);if(existing){switchProfile(existing.id);return}let p={id:uid(),name:name.slice(0,18)};DB.profiles.push(p);switchProfile(p.id)});
document.addEventListener('input',e=>{if(e.target.id==='openAnswer'&&S.screen==='game'&&!outcome()){draft().text=e.target.value;save();$('#confirm').disabled=!ready()}});
document.addEventListener('keydown',e=>{if(e.repeat)return;if(S.modal)return;if(document.activeElement?.classList.contains('markable')&&['Enter',' '].includes(e.key)){e.preventDefault();document.activeElement.click();return}const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'&&S.screen==='game'){e.preventDefault();pause();return}if(S.screen==='home'){if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();chooseRelative(e.key==='ArrowRight'?1:-1)}if(e.key==='Enter'&&document.activeElement?.tagName!=='BUTTON'){e.preventDefault();requestStart(S.stage)}return}if(S.screen!=='game')return;let q=curQ();if((q.type==='single'||q.type==='multi')&&!outcome()){let n=Number(e.key);if(n>=1&&n<=q.options.length){e.preventDefault();chooseOption(n-1);return}}if(e.key==='Enter'&&document.activeElement?.tagName!=='BUTTON'&&ready()){e.preventDefault();outcome()?next():submit()}});
document.addEventListener('pointerdown',dragBegin);document.addEventListener('pointermove',dragMove,{passive:false});document.addEventListener('pointerup',dragEnd,{passive:false});document.addEventListener('pointercancel',dragCancel);
$('#dialog').addEventListener('close',()=>{S.modal=null;startClock()});$('#dialog').addEventListener('cancel',()=>{S.modal=null;startClock()});
$('#importFile').addEventListener('change',e=>importData(e.target.files[0]));
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopClock();save()}else startClock()});
window.addEventListener('pagehide',()=>{stopClock();save()});
let ticks=0;setInterval(()=>{if(S.screen==='game'&&!S.modal){const clock=$('#clock');if(clock)clock.textContent=fmt(timeNow());if(++ticks%10===0){stopClock();startClock()}}},1000);
// Validate the retained bank once; never silently drop an unsupported question.
if(Object.keys(Q).length!==35)throw Error('Question bank must contain 35 unique questions.');
if(new Set(STAGES.filter(s=>s.id!=='mixed').flatMap(s=>s.qids)).size!==35)throw Error('Subject modules must cover the full question bank.');
applySettings();save();home();

